pragma solidity 0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @dev The locked token must let its holder burn its own balance. RLS is
///      `ERC20Burnable`, which provides exactly this.
interface IERC20Burnable {
    function burn(uint256 value) external;
}

/**
 * @title RlsTokenLock
 * @author Rayls Team
 * @notice Holds a fixed amount of RLS and unlocks it in equal tranches on fixed
 *         calendar dates. Admins claim the unlocked tokens; the caller receives
 *         them.
 * @dev Vesting is computed from the declared `totalAmount` less everything burned,
 *      never from the live balance, so a stray transfer in cannot change what a
 *      tranche pays.
 *
 *      Rules:
 *
 *      1. **Not upgradeable.** The terms at deployment are the terms forever.
 *      2. **No early unlock.** No key can move a tranche before its date.
 *      3. **Funding is checked against the token.** While a date is still to come,
 *         {claim} pays nothing unless `balanceOf(this) >= outstanding()`. After the
 *         last date the guard is dropped, since nothing remains to strand, so no
 *         balance is ever unreachable. See {claim}.
 *      4. **Burning re-levels, it never skips a date.** {burn} lowers {outstanding},
 *         and later claims share what is left over the dates not yet settled. The
 *         schedule always pays `totalAmount - totalBurned` in total; only the split
 *         moves.
 *      5. **Tokens leave only through {claim}, {burn} and {sweep}.** No withdraw, no
 *         rescue. Any token other than RLS sent here is unrecoverable.
 *
 *      Two permission sets, deliberately separate:
 *
 *      - **Owners** manage permissions only. Flat: every owner can remove any other,
 *        including itself. The deployer is the first owner.
 *      - **Admins** move tokens only. Any admin can claim everything unlocked and burn
 *        the rest. A new deployment has none.
 *
 *      Removing the last owner freezes the admin set permanently, and is refused if no
 *      admin would be left, which would put every token beyond reach. See
 *      {removeOwner}.
 *
 *      Funding is a plain transfer to this address, at any time, in any number of
 *      payments. There is no deposit function and no deadline.
 *
 * @custom:security-contact secops@parfin.io
 * @custom:version 1.0.0
 */
contract RlsTokenLock is ReentrancyGuard {
    using SafeERC20 for IERC20;

    /// @notice Upper bound on schedule length, so every schedule loop is cheap.
    uint256 public constant MAX_TRANCHES = 48;

    /// @notice Upper bound on how far past deployment the last unlock may fall.
    /// @dev Catches a schedule passed in milliseconds or as block numbers. Either still
    ///      increases and starts in the future, so every other check passes it, and the
    ///      dates land centuries out where nothing can ever be claimed.
    uint256 public constant MAX_SCHEDULE_HORIZON = 3650 days;

    /// @notice The locked token (RLS).
    IERC20 public immutable token;

    /// @notice The amount this contract was declared to hold at deployment. Fixed
    ///         forever. See {scheduleBasis} for the figure the schedule divides
    ///         (this less {totalBurned}) and {outstanding} for what is still
    ///         locked (that less {totalClaimed}).
    uint256 public immutable totalAmount;

    /// @dev Unlock timestamps, strictly increasing. Written once, in the
    ///      constructor; there is no setter.
    uint256[] private _unlockTimes;

    /// @dev Addresses allowed to manage the owner and admin sets. Flat: every
    ///      owner holds the same powers, including over other owners.
    mapping(address => bool) private _owners;

    /// @notice Number of current owners.
    uint256 public ownerCount;

    /// @dev Addresses allowed to call {claim} and {burn}.
    mapping(address => bool) private _admins;

    /// @notice Number of current admins.
    uint256 public adminCount;

    /// @notice Total already claimed out of {scheduleBasis}.
    uint256 public totalClaimed;

    /// @notice How many tranches have been settled. Each unlock date releases a
    ///         share of the basis *as it stands when that tranche is claimed*, so
    ///         the count has to be tracked rather than derived from
    ///         {totalClaimed}.
    uint256 public tranchesClaimed;

    /// @notice Total burned so far. {totalAmount} less this is the amount
    ///         the schedule now divides into tranches.
    uint256 public totalBurned;

    /// @notice Emitted once, at deployment, recording the terms this lock is
    ///         bound to for the whole of its life. None of them can ever change,
    ///         so this single log entry is the complete statement of the lock's
    ///         rules, enough for an outside observer to verify the commitment
    ///         without reading storage or decoding constructor calldata.
    /// @param token The locked token.
    /// @param totalAmount The amount the lock is declared to hold and pay out.
    /// @param unlockTimes The full schedule, in strictly increasing order.
    event LockCreated(address indexed token, uint256 totalAmount, uint256[] unlockTimes);

    /// @notice Emitted when an address gains the right to manage the owner and
    ///         admin sets.
    event OwnerAdded(address indexed owner, address indexed by);

    /// @notice Emitted when an address loses the right to manage those sets.
    event OwnerRemoved(address indexed owner, address indexed by);

    /// @notice Emitted when an address gains the right to claim.
    event AdminAdded(address indexed admin, address indexed by);

    /// @notice Emitted when an address loses the right to claim.
    event AdminRemoved(address indexed admin, address indexed by);

    /// @notice Emitted when unlocked tokens are claimed.
    /// @param admin The admin that called and received the tokens.
    /// @param amount Amount transferred in this claim.
    /// @param newTotalClaimed Cumulative claimed after this call.
    /// @param newTranchesClaimed {tranchesClaimed} after this call. A single claim
    ///        settles every tranche that has unlocked since the last one, so the
    ///        amount alone does not say how much of the schedule this call covered.
    event Claimed(address indexed admin, uint256 amount, uint256 newTotalClaimed, uint256 newTranchesClaimed);

    /// @notice Emitted when an admin burns part of the locked amount.
    /// @param admin The admin that called.
    /// @param amount Amount burned.
    /// @param newLockedAmount {scheduleBasis} after the burn, everything the lock
    ///        will still pay out in total. Not the figure a single tranche is a
    ///        share of: that is {outstanding}, divided by the dates not yet
    ///        settled. See {claimable}.
    event Burned(address indexed admin, uint256 amount, uint256 newLockedAmount);

    /// @notice Emitted when an admin sweeps the surplus after the schedule settles.
    /// @param admin The admin that called and received the tokens.
    /// @param amount Amount transferred out.
    event Swept(address indexed admin, uint256 amount);

    /// @notice Thrown when a zero address is provided where it is not allowed.
    error ZeroAddress();

    /// @notice Thrown when the token address has no contract code. The token is
    ///         immutable and there is no rescue, so a mistyped address would brick
    ///         the lock permanently; this catches the case cheaply at deployment.
    /// @dev An address that *does* hold code but is not an ERC-20 is caught by the
    ///      constructor's `balanceOf` probe instead, which reverts in the token's own
    ///      terms rather than this contract's.
    error TokenNotAContract(address token);

    /// @notice Thrown when a zero amount is provided where it is not allowed.
    error ZeroAmount();

    /// @notice Thrown when the constructor is given an empty schedule.
    error EmptySchedule();

    /// @notice Thrown when the schedule is longer than {MAX_TRANCHES}.
    error TooManyTranches(uint256 provided, uint256 max);

    /// @notice Thrown when schedule timestamps are not strictly increasing.
    error ScheduleNotIncreasing(uint256 index);

    /// @notice Thrown when the first unlock is not strictly in the future.
    error FirstUnlockNotInFuture(uint256 firstUnlockTime, uint256 blockTimestamp);

    /// @notice Thrown when the last unlock falls further than {MAX_SCHEDULE_HORIZON}
    ///         past deployment, the signature of a schedule passed in the wrong
    ///         unit.
    error ScheduleHorizonTooFar(uint256 lastUnlockTime, uint256 latestAllowed);

    /// @notice Thrown when a non-owner calls an owner-only function.
    error NotOwner(address caller);

    /// @notice Thrown when adding an address that is already an owner.
    error AlreadyOwner(address owner);

    /// @notice Thrown when removing an address that is not an owner.
    error NotAnOwner(address owner);

    /// @notice Thrown when removing the last owner would leave the lock with no
    ///         admin. Both sets empty means no token the lock holds, or is ever sent
    ///         afterwards, can be reached by anyone. Appoint an admin first.
    error RemovingLastOwnerRequiresAnAdmin();

    /// @notice Thrown when a non-admin calls an admin-only function.
    error NotAdmin(address caller);

    /// @notice Thrown when adding an address that is already an admin.
    error AlreadyAdmin(address admin);

    /// @notice Thrown when removing an address that is not an admin.
    error NotAnAdmin(address admin);

    /// @notice Thrown when claiming before the first tranche unlocks.
    error NotYetVested(uint256 firstUnlockTime);

    /// @notice Thrown when everything unlocked so far has already been claimed.
    error NothingToClaim();

    /// @notice Thrown when the contract holds less than it still owes, so paying
    ///         now could leave a later tranche unpayable.
    error NotFullyFunded(uint256 required, uint256 held);

    /// @notice Thrown when a burn is larger than the amount still under the
    ///         schedule, i.e. it would reach into a surplus that was never locked.
    error BurnExceedsLocked(uint256 requested, uint256 locked);

    /// @notice Thrown when the token's own `burn` returned successfully without
    ///         removing exactly `requested` from **both** this contract's balance and
    ///         the total supply. {totalBurned} is what the schedule divides by, so
    ///         accepting a burn that did not happen would credit a burn that never
    ///         occurred and turn the tokens into a sweepable surplus. The whole call
    ///         is reverted instead.
    /// @param requested The amount the lock asked the token to burn.
    /// @param balanceRemoved How much left this contract's balance. Equal to
    ///        `requested` while `supplyRemoved` is 0 means the token moved the tokens
    ///        somewhere rather than destroying them.
    /// @param supplyRemoved How much left the total supply. Equal to `requested` while
    ///        `balanceRemoved` is 0 means the token burned somebody else's balance.
    error BurnNotConfirmed(uint256 requested, uint256 balanceRemoved, uint256 supplyRemoved);

    /// @notice Thrown when a `transfer` out returned successfully without moving
    ///         exactly `requested` out of this contract. {claim} and {sweep} write
    ///         their ledger entries before transferring, so a transfer that silently
    ///         moved nothing would record a payment nobody received.
    error TransferNotConfirmed(uint256 requested, uint256 moved);

    /// @notice Thrown when {sweep} is called while the schedule still owes
    ///         something. The surplus is only reachable once nothing is
    ///         {outstanding}.
    error ScheduleNotSettled(uint256 outstandingAmount);

    /// @notice Thrown when {sweep} would move nothing.
    error NothingToSweep();

    /// @dev Restricts a function to the owner set.
    modifier onlyOwner() {
        if (!_owners[msg.sender]) revert NotOwner(msg.sender);
        _;
    }

    /// @dev Restricts a function to the admin set.
    modifier onlyAdmin() {
        if (!_admins[msg.sender]) revert NotAdmin(msg.sender);
        _;
    }

    /**
     * @param token_ The locked token (RLS on the target chain).
     * @param totalAmount_ The amount this lock is declared to hold and pay out in full
     *        across the schedule. Checked against the real balance before any claim.
     * @param unlockTimes_ Unlock timestamps, strictly increasing, in unix seconds. Each
     *        releases roughly `1 / unlockTimes_.length` and the last pays the
     *        remainder, so nothing is stranded. Only the total is exact: claiming at
     *        every date leaves the shares at most one wei apart, and letting dates go
     *        by widens that to at most `unlockTimes_.length - 1` wei. See {claimable}.
     *        The first date must be in the future, the last within
     *        {MAX_SCHEDULE_HORIZON}.
     * @dev The deployer becomes the first owner and nothing else, so a new lock has no
     *      address that can claim or burn until an owner calls {addAdmin}. Moving
     *      tokens should be granted explicitly, not fall out of who deployed.
     *
     *      Hand over to a multisig with {addOwner} then {removeOwner}.
     */
    constructor(IERC20 token_, uint256 totalAmount_, uint256[] memory unlockTimes_) {
        if (address(token_) == address(0)) revert ZeroAddress();
        if (address(token_).code.length == 0) revert TokenNotAContract(address(token_));
        if (totalAmount_ == 0) revert ZeroAmount();

        uint256 count = unlockTimes_.length;
        if (count == 0) revert EmptySchedule();
        if (count > MAX_TRANCHES) revert TooManyTranches(count, MAX_TRANCHES);
        if (unlockTimes_[0] <= block.timestamp) {
            revert FirstUnlockNotInFuture(unlockTimes_[0], block.timestamp);
        }
        for (uint256 i = 1; i < count; i++) {
            if (unlockTimes_[i] <= unlockTimes_[i - 1]) revert ScheduleNotIncreasing(i);
        }
        // The schedule is increasing, so the last entry is the furthest out.
        uint256 latestAllowed = block.timestamp + MAX_SCHEDULE_HORIZON;
        if (unlockTimes_[count - 1] > latestAllowed) {
            revert ScheduleHorizonTooFar(unlockTimes_[count - 1], latestAllowed);
        }

        token = token_;
        totalAmount = totalAmount_;
        _unlockTimes = unlockTimes_;

        _owners[msg.sender] = true;
        ownerCount = 1;

        emit LockCreated(address(token_), totalAmount_, unlockTimes_);
        emit OwnerAdded(msg.sender, msg.sender);

        // Code alone does not make an address a token, and every function here reads
        // the balance. Probing it turns "a contract, but the wrong one" into a failed
        // deployment rather than a lock whose every view reverts for ever with no way
        // to correct the address.
        //
        // The balance itself proves nothing and is not required to be zero, since an
        // address can hold tokens before a contract is deployed to it. Only the answer
        // matters: a real ERC-20 returns 32 bytes, anything else is not one.
        //
        // Placed last on purpose. Everything above is rolled back if this fails, so the
        // result is identical to checking first, and no state is written after an
        // external call.
        (bool ok, bytes memory answer) = address(token_).staticcall(abi.encodeCall(IERC20.balanceOf, (address(this))));
        if (!ok || answer.length < 32) revert TokenNotAContract(address(token_));
    }

    // ---------------------------------------------------------------------
    // Owner set, owners only
    // ---------------------------------------------------------------------

    /**
     * @notice Grant `newOwner` the right to manage the owner and admin sets.
     * @dev The set is flat: a new owner holds exactly the same powers as the
     *      deployer, including adding and removing other owners and removing the
     *      address that added it. There is no root owner to fall back on.
     *
     *      Being an owner is not being an admin. This grants no ability to claim
     *      or burn; for that the address must also be passed to {addAdmin}.
     */
    function addOwner(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress();
        if (_owners[newOwner]) revert AlreadyOwner(newOwner);

        _owners[newOwner] = true;
        ownerCount += 1;

        emit OwnerAdded(newOwner, msg.sender);
    }

    /**
     * @notice Revoke `owner_`'s right to manage the owner and admin sets. An owner
     *         may remove itself.
     * @dev Removing the last owner is allowed and permanent. The admin set can never
     *      change again, while existing admins keep claiming, burning and sweeping.
     *      That is the deliberate way to freeze permissions.
     *
     *      Refused if no admin would be left. Tokens leave only through admin-only
     *      functions and only an owner can appoint an admin, so both sets empty would
     *      put every token beyond reach, including anything sent later.
     *
     *      Counting admins rather than testing a balance is what covers funds that have
     *      not arrived yet. It cannot establish that an admin is controllable, so
     *      appointing an address nobody holds satisfies the check and protects nothing.
     */
    function removeOwner(address owner_) external onlyOwner {
        if (!_owners[owner_]) revert NotAnOwner(owner_);

        if (ownerCount == 1 && adminCount == 0) revert RemovingLastOwnerRequiresAnAdmin();

        _owners[owner_] = false;
        ownerCount -= 1;

        emit OwnerRemoved(owner_, msg.sender);
    }

    /// @notice Whether `account` may manage the owner and admin sets.
    function isOwner(address account) external view returns (bool) {
        return _owners[account];
    }

    // ---------------------------------------------------------------------
    // Admin set, owners only
    // ---------------------------------------------------------------------

    /**
     * @notice Grant `admin` the right to call {claim} and {burn}. Callable by any
     *         owner.
     * @dev This is equivalent to granting a claim on everything currently
     *      unlocked, and the power to burn the rest. It cannot unlock anything
     *      early.
     */
    function addAdmin(address admin) external onlyOwner {
        if (admin == address(0)) revert ZeroAddress();
        if (_admins[admin]) revert AlreadyAdmin(admin);

        _admins[admin] = true;
        adminCount += 1;

        emit AdminAdded(admin, msg.sender);
    }

    /**
     * @notice Revoke `admin`'s right to call {claim} and {burn}. Callable by any
     *         owner.
     * @dev The admin set may be emptied entirely; the lock then has no claimant
     *      until an owner adds one, and the schedule is unaffected either way.
     *      Emptying it does constrain {removeOwner}, see the guard there.
     */
    function removeAdmin(address admin) external onlyOwner {
        if (!_admins[admin]) revert NotAnAdmin(admin);

        _admins[admin] = false;
        adminCount -= 1;

        emit AdminRemoved(admin, msg.sender);
    }

    /// @notice Whether `account` may call {claim}.
    function isAdmin(address account) external view returns (bool) {
        return _admins[account];
    }

    // ---------------------------------------------------------------------
    // Paying out
    // ---------------------------------------------------------------------

    /**
     * @dev Reverts unless the contract holds everything the schedule still owes.
     *
     *      Takes the balance rather than reading it, because both callers have already
     *      read it and neither should pay for a second call to the token.
     * @param held What the contract holds, per `token.balanceOf(address(this))`.
     */
    function _assertFullyFunded(uint256 held) private view {
        uint256 owed = outstanding();
        if (held < owed) revert NotFullyFunded(owed, held);
    }

    /**
     * @dev Send `amount` out and confirm it really left.
     *
     *      {claim} and {sweep} record the payment before transferring, so a token whose
     *      `transfer` reports success without moving anything would leave the ledger
     *      claiming a payment nobody received. `SafeERC20` does not cover this: it only
     *      establishes that the call neither reverted nor returned false.
     */
    function _transferOut(address to, uint256 amount) private {
        uint256 heldBefore = token.balanceOf(address(this));
        token.safeTransfer(to, amount);
        uint256 heldAfter = token.balanceOf(address(this));

        // Guarded rather than a plain subtraction: a token that credits this contract
        // during its own transfer would make the balance rise, and an underflow here
        // would panic instead of reporting the mismatch.
        uint256 moved = heldAfter >= heldBefore ? 0 : heldBefore - heldAfter;
        if (moved != amount) revert TransferNotConfirmed(amount, moved);
    }

    // ---------------------------------------------------------------------
    // Claiming
    // ---------------------------------------------------------------------

    /**
     * @notice Claim everything unlocked so far and not yet claimed. The caller
     *         receives the tokens.
     * @dev Takes no arguments: the amount comes from the schedule. Reverts rather than
     *      paying zero. {NotYetVested} before the first date, {NothingToClaim} when the
     *      unlocked portion is already drawn, {NotFullyFunded} when the lock is short.
     *
     *      The funding guard applies only while a date is still to come. It exists to
     *      stop an early payment from leaving a later date unpayable.
     *
     *      After the last date there is no later date to protect, so a short lock pays
     *      what it holds. Without that, a lock funded below `totalAmount` would have no
     *      way out at all: {burn} is gated on the same condition and cannot close a
     *      shortfall, and {sweep} stays shut while anything is owed. Everything
     *      delivered would be unreachable.
     *
     *      A payment cut short does not advance {tranchesClaimed}. The remainder stays
     *      owed and claimable if the shortfall is funded later.
     * @return amount The amount transferred to the caller.
     */
    function claim() external nonReentrant onlyAdmin returns (uint256 amount) {
        uint256 firstUnlock = _unlockTimes[0];
        if (block.timestamp < firstUnlock) revert NotYetVested(firstUnlock);

        amount = claimable();
        if (amount == 0) revert NothingToClaim();

        uint256 held = token.balanceOf(address(this));
        uint256 unlocked = unlockedTranches(block.timestamp);

        if (unlocked < _unlockTimes.length) {
            // A date is still to come, so everything still owed must be here.
            _assertFullyFunded(held);
            tranchesClaimed = unlocked;
        } else if (held >= amount) {
            // Last date, fully funded. `amount` is the whole outstanding balance.
            tranchesClaimed = unlocked;
        } else if (held > 0) {
            // Last date, short. Nothing later can be stranded, so pay what is here and
            // leave the rest owed and claimable.
            amount = held;
        } else {
            revert NotFullyFunded(amount, 0);
        }

        totalClaimed += amount;
        emit Claimed(msg.sender, amount, totalClaimed, tranchesClaimed);

        _transferOut(msg.sender, amount);
    }

    // ---------------------------------------------------------------------
    // Burning
    // ---------------------------------------------------------------------

    /**
     * @notice Burn `amount` of the locked tokens. Callable at any time, before
     *         or after any unlock date, for any amount the contract still holds
     *         under the schedule.
     * @dev Reduces {scheduleBasis} and so {outstanding}. Later claims share what is
     *      left over the dates not yet settled, and the last date pays the remainder,
     *      so rounding strands nothing. A burn thins the schedule, it never skips a
     *      date. Burning everything {outstanding} simply ends the schedule early.
     *
     *      Ordering changes the split, never the total: the lock always pays
     *      `totalAmount - totalBurned`. On a 100/4 schedule, claiming the first quarter
     *      then burning 50 pays 25 + 8.33 + 8.33 + 8.33; burning 50 first pays 12.5
     *      four times. Both total 50.
     *
     *      Bounded by {outstanding}, because a surplus was never part of the schedule
     *      and reaching it would drive {scheduleBasis} below {totalClaimed}. That bound
     *      is what stops {outstanding} underflowing. Combined with the funding
     *      precondition, `amount <= outstanding() <= balanceOf(this)`, so the tokens
     *      are always there and no separate balance bound is needed.
     * @param amount Amount to burn, in the token's base units.
     */
    // Slither reports `reentrancy-balance` for the balance read before `token.burn` and
    // compared after it. That comparison is the check: it measures net movement across
    // the call, so anything the token does in between is inside the figure, not hidden
    // from it. See docs/security.md.
    // slither-disable-next-line reentrancy-balance
    function burn(uint256 amount) external nonReentrant onlyAdmin {
        if (amount == 0) revert ZeroAmount();

        // Fund the shortfall before burning anything. A burn lowers the balance and
        // {outstanding} by the same amount, so it can never close a shortfall, only
        // destroy tokens a later top-up could still have paid out. Unlike {claim}, this
        // guard is not lifted after the last date.
        uint256 held = token.balanceOf(address(this));
        _assertFullyFunded(held);

        uint256 locked = outstanding();
        if (amount > locked) revert BurnExceedsLocked(amount, locked);

        uint256 supplyBefore = token.totalSupply();

        totalBurned += amount;
        emit Burned(msg.sender, amount, scheduleBasis());

        IERC20Burnable(address(token)).burn(amount);

        // Confirm the token really burned it. `burn(uint256)` is not part of ERC-20 and
        // is reached through a raw cast, so the effect is checked rather than assumed.
        // Balance and supply must both fall by `amount`: balance alone would accept a
        // burn that moved the tokens elsewhere, supply alone would accept one taken
        // from another account.
        uint256 heldAfter = token.balanceOf(address(this));
        uint256 supplyAfter = token.totalSupply();
        uint256 balanceRemoved = heldAfter >= held ? 0 : held - heldAfter;
        uint256 supplyRemoved = supplyAfter >= supplyBefore ? 0 : supplyBefore - supplyAfter;
        if (balanceRemoved != amount || supplyRemoved != amount) {
            revert BurnNotConfirmed(amount, balanceRemoved, supplyRemoved);
        }
    }

    // ---------------------------------------------------------------------
    // Sweeping the surplus
    // ---------------------------------------------------------------------

    /**
     * @notice Transfer everything this contract still holds to the caller, once the
     *         schedule owes nothing at all. Admin only.
     * @dev The recovery path for a surplus: RLS sent here beyond `totalAmount`. A
     *      surplus is never payable through {claim}, which pays from the declared
     *      figure, and {burn} is bounded by {outstanding}, so without this it would sit
     *      here forever.
     *
     *      Gated on `outstanding() == 0`, meaning everything declared has been claimed
     *      or burned. Safe because {outstanding} only ever falls: `totalAmount` is
     *      immutable while {totalClaimed} and {totalBurned} only rise. So no sweep can
     *      take tokens a later claim was owed.
     *
     *      That also means the gate never closes again. Any RLS sent to a settled lock
     *      can be taken by any admin. Treat a settled lock as a closed account.
     *
     *      Deliberately not gated on `tranchesClaimed == trancheCount()`: an allocation
     *      that was burned rather than claimed never advances {tranchesClaimed}, so
     *      that gate would strand the surplus permanently.
     *
     *      Only the locked token moves. Any other ERC-20 sent here stays unrecoverable.
     * @return amount The amount transferred to the caller.
     */
    function sweep() external nonReentrant onlyAdmin returns (uint256 amount) {
        uint256 owed = outstanding();
        if (owed > 0) revert ScheduleNotSettled(owed);

        amount = token.balanceOf(address(this));
        if (amount == 0) revert NothingToSweep();

        emit Swept(msg.sender, amount);

        _transferOut(msg.sender, amount);
    }

    // ---------------------------------------------------------------------
    // Views
    // ---------------------------------------------------------------------

    /// @notice The full unlock schedule, in increasing order.
    function unlockTimes() external view returns (uint256[] memory) {
        return _unlockTimes;
    }

    /// @notice The unlock timestamp of tranche `index` (0-based).
    function unlockTimeAt(uint256 index) external view returns (uint256) {
        return _unlockTimes[index];
    }

    /// @notice Number of tranches in the schedule.
    function trancheCount() external view returns (uint256) {
        return _unlockTimes.length;
    }

    /// @notice First unlock timestamp, before this, nothing can be claimed.
    function firstUnlockTime() external view returns (uint256) {
        return _unlockTimes[0];
    }

    /// @notice Last timestamp of the schedule: when everything is unlocked.
    function fullyUnlockedAt() external view returns (uint256) {
        return _unlockTimes[_unlockTimes.length - 1];
    }

    /// @notice Next unlock timestamp, or 0 once the schedule is exhausted.
    function nextUnlockTime() external view returns (uint256) {
        uint256 count = _unlockTimes.length;
        for (uint256 i = 0; i < count; i++) {
            if (block.timestamp < _unlockTimes[i]) return _unlockTimes[i];
        }
        return 0;
    }

    /// @notice How many tranches have unlocked as of `timestamp`.
